import heapq
from typing import List

class Solution:
    def findMaximizedCapital(self, k: int, w: int, profits: List[int], capital: List[int]) -> int:
        projects = sorted(zip(capital, profits))
        n = len(projects)
        idx = 0
        max_heap = []

        for _ in range(k):
            while idx < n and projects[idx][0] <= w:
                heapq.heappush(max_heap, -projects[idx][1])
                idx += 1
            if not max_heap:
                break
            w += -heapq.heappop(max_heap)

        return w

class Solution {
public:
    int findMaximizedCapital(int k, int w, vector<int>& profits, vector<int>& capital) {
        int n = profits.size();
        vector<pair<int, int>> projects(n);
        for (int i = 0; i < n; i++) {
            projects[i] = {capital[i], profits[i]};
        }
        sort(projects.begin(), projects.end());

        priority_queue<int> max_heap;
        int idx = 0;

        for (int i = 0; i < k; i++) {
            while (idx < n && projects[idx].first <= w) {
                max_heap.push(projects[idx].second);
                idx++;
            }
            if (max_heap.empty()) break;
            w += max_heap.top();
            max_heap.pop();
        }
        return w;
    }
};

class Solution {
    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        int n = profits.length;
        int[][] projects = new int[n][2];
        for (int i = 0; i < n; i++) {
            projects[i][0] = capital[i];
            projects[i][1] = profits[i];
        }
        java.util.Arrays.sort(projects, java.util.Comparator.comparingInt(a -> a[0]));

        java.util.PriorityQueue<Integer> maxHeap = new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
        int idx = 0;

        for (int i = 0; i < k; i++) {
            while (idx < n && projects[idx][0] <= w) {
                maxHeap.offer(projects[idx][1]);
                idx++;
            }
            if (maxHeap.isEmpty()) break;
            w += maxHeap.poll();
        }
        return w;
    }
}

/**
 * @param {number} k
 * @param {number} w
 * @param {number[]} profits
 * @param {number[]} capital
 * @return {number}
 */
var findMaximizedCapital = function(k, w, profits, capital) {
    const n = profits.length;
    const projects = [];
    for (let i = 0; i < n; i++) {
        projects.push([capital[i], profits[i]]);
    }
    projects.sort((a, b) => a[0] - b[0]);

    const maxHeap = [];
    const pushHeap = (val) => {
        maxHeap.push(val);
        let i = maxHeap.length - 1;
        while (i > 0) {
            const p = Math.floor((i - 1) / 2);
            if (maxHeap[p] >= maxHeap[i]) break;
            [maxHeap[p], maxHeap[i]] = [maxHeap[i], maxHeap[p]];
            i = p;
        }
    };
    const popHeap = () => {
        const top = maxHeap[0];
        const last = maxHeap.pop();
        if (maxHeap.length > 0) {
            maxHeap[0] = last;
            let i = 0;
            while (true) {
                let best = i;
                const left = 2 * i + 1, right = 2 * i + 2;
                if (left < maxHeap.length && maxHeap[left] > maxHeap[best]) best = left;
                if (right < maxHeap.length && maxHeap[right] > maxHeap[best]) best = right;
                if (best === i) break;
                [maxHeap[i], maxHeap[best]] = [maxHeap[best], maxHeap[i]];
                i = best;
            }
        }
        return top;
    };

    let idx = 0;
    for (let round = 0; round < k; round++) {
        while (idx < n && projects[idx][0] <= w) {
            pushHeap(projects[idx][1]);
            idx++;
        }
        if (maxHeap.length === 0) break;
        w += popHeap();
    }
    return w;
};
